import { EosGradientBanner } from "@/components/application/eos/gradient-banner";

/** A grain gradient holding app tiles: white tiles on dawn, frosted ones on orchid. */
export default function EosGradientBannerDemo() {
  return (
    <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(min(100%, 280px), 1fr))", gap: 16, width: "100%", maxWidth: 760, margin: "0 auto" }}>
      <EosGradientBanner gradient="dawn" apps={["calendar", "mail", "notes"]} shape="card" height={220} />
      <EosGradientBanner gradient="orchid" apps={["books", "mail"]} tileTone="frosted" tileSize="lg" shape="card" height={220} flip />
    </div>
  );
}

